	private static Result execute(NativeSubqueryPlan original, SyntheticValueSource root, String name,
			CyclicBarrier ready) throws Exception {
		QueryBindingSet base = new QueryBindingSet();
		base.setBinding(name, SimpleValueFactory.getInstance().createLiteral(name));
		SyntheticValueSource source = root.forInvocation(base);
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("graph", 0), null);
		layout.freeze(List.of("graph"));
		Value graph = SimpleValueFactory.getInstance().createIRI("urn:worker-graph:" + name);
		try {
			NativeSubqueryPlan bound = original.forWorker(new NativeScalarPlan.WorkerContext(source, null, null));
			RowState row = new RowState(source, layout, base);
			assertThat(NativeRowSeeder.seed(row.slots, layout, base, source)).isTrue();
			row.recomputeBoundMask();
			long graphId = source.internComputedValue(graph);
			assertThat(source.lazyValue(graphId))
					.as("the admitted graph id must resolve in this exact worker authority")
					.isEqualTo(graph);
			assertThat(row.bind(0, graphId)).isTrue();
			assertThat(row.view.getValue("graph")).isEqualTo(graph);
			assertThat(row.view.getValue(name)).isEqualTo(base.getValue(name));
			ready.await(10, TimeUnit.SECONDS);
			ExistsFilter nested = new ExistsFilter(new FilterPlan(bound, new ExistsFilter(SlotPlan.singleton()), -1L));
			try {
				boolean accepted = nested.accept(row);
				boolean replayed = nested.accept(row);
				return new Result(source.executionContext(), graph, Thread.currentThread().threadId(),
						accepted && replayed);
			} finally {
				nested.close();
				row.closeDecodedInputs();
			}
		} finally {
			source.executionContext().close();
		}
	}

	private record Result(NativeExecutionContext execution, Value graph, long thread, boolean accepted) {
	}
